INSERT OR IGNORE INTO self_check_tests (id,slug,version,title,description,subject,topic,level,estimated_minutes,status) VALUES
('linearni-rovnice-dan-v1','linearni-rovnice-dan',1,'Lineární rovnice — Dan (36 úloh)','[[calculator:Bez kalkulačky]]36 úloh / 69 bodů / 40–55 minut. Šest bloků: význam rovnice, ekvivalentní úpravy, závorky a znaménka, zlomky, počet řešení a grafická interpretace, slovní úlohy. Hodnocení po odevzdání včetně jednotlivých vysvětlení a možnosti vyhodnotit zodpovězenou část.','Matematika','Lineární rovnice','ZŠ / SŠ',50,'published');

INSERT OR IGNORE INTO self_check_questions (id,test_id,position,prompt,options_json,correct_answer,explanation,points) VALUES
  ('linearni-rovnice-dan-v1-q01','linearni-rovnice-dan-v1',1,'{"instruction":"Urči řešení rovnice.","math":"3x+2=14","category":"01 / Význam rovnice","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 3"},{"id":"b","label":"x = 4"},{"id":"c","label":"x = 5"},{"id":"d","label":"x = 12"}]','b','Po odečtení 2 je 3x=12, tedy x=4.',1),
  ('linearni-rovnice-dan-v1-q02','linearni-rovnice-dan-v1',2,'{"instruction":"Která úprava zachová množinu řešení?","math":"x+7=12","category":"01 / Význam rovnice","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Odečíst 7 pouze z levé strany"},{"id":"b","label":"Odečíst 7 z obou stran"},{"id":"c","label":"Vynásobit pouze pravou stranu 2"},{"id":"d","label":"Vydělit obě strany nulou"}]','b','U rovnosti odečítáme stejnou hodnotu z obou stran.',1),
  ('linearni-rovnice-dan-v1-q03','linearni-rovnice-dan-v1',3,'{"instruction":"Vyřeš rovnici se záporným koeficientem.","math":"-4x=20","category":"01 / Význam rovnice","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 5"},{"id":"b","label":"x = −5"},{"id":"c","label":"x = −16"},{"id":"d","label":"x = 80"}]','b','Obě strany vydělíme −4: x=−5.',1),
  ('linearni-rovnice-dan-v1-q04','linearni-rovnice-dan-v1',4,'{"instruction":"Vyřeš rovnici s dělením.","math":"\\frac{x}{3}=5","category":"01 / Význam rovnice","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 2"},{"id":"b","label":"x = 15"},{"id":"c","label":"x = 8"},{"id":"d","label":"x = 5/3"}]','b','Obě strany násobíme nenulovou trojkou: x=15.',1),
  ('linearni-rovnice-dan-v1-q05','linearni-rovnice-dan-v1',5,'{"instruction":"Která hodnota splňuje rovnici?","math":"x-7=-1","category":"01 / Význam rovnice","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = −8"},{"id":"b","label":"x = 8"},{"id":"c","label":"x = 6"},{"id":"d","label":"x = −6"}]','c','Přičtením 7 k oběma stranám dostaneme x=6.',1),
  ('linearni-rovnice-dan-v1-q06','linearni-rovnice-dan-v1',6,'{"instruction":"Kolik řešení má tato rovnice?","math":"0\\cdot x+0=0","category":"01 / Význam rovnice","hint":"Rozhodni, zda rovnost platí nezávisle na x."}','[{"id":"a","label":"Žádné"},{"id":"b","label":"Právě jedno"},{"id":"c","label":"Právě dvě"},{"id":"d","label":"Nekonečně mnoho"}]','d','Jde o identitu 0=0, kterou splňuje každé reálné x.',1),
  ('linearni-rovnice-dan-v1-q07','linearni-rovnice-dan-v1',7,'{"instruction":"Urči neznámou.","math":"5x-9=16","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 7"},{"id":"b","label":"x = 5"},{"id":"c","label":"x = 1"},{"id":"d","label":"x = −5"}]','b','Přičteme 9: 5x=25; dělíme 5: x=5.',2),
  ('linearni-rovnice-dan-v1-q08','linearni-rovnice-dan-v1',8,'{"instruction":"Pozor na znaménko při dělení.","math":"7-2x=13","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = −3"},{"id":"b","label":"x = 3"},{"id":"c","label":"x = −10"},{"id":"d","label":"x = 10"}]','a','Po odečtení 7: −2x=6, tedy x=−3.',2),
  ('linearni-rovnice-dan-v1-q09','linearni-rovnice-dan-v1',9,'{"instruction":"Převeď členy s x na jednu stranu.","math":"2x+4=x-1","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 5"},{"id":"b","label":"x = −5"},{"id":"c","label":"x = −3"},{"id":"d","label":"x = 3"}]','b','Odečti x a 4: x=−5.',2),
  ('linearni-rovnice-dan-v1-q10','linearni-rovnice-dan-v1',10,'{"instruction":"Vyřeš rovnici s x na obou stranách.","math":"4x-3=2x+9","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 3"},{"id":"b","label":"x = −6"},{"id":"c","label":"x = 6"},{"id":"d","label":"x = 12"}]','c','Odečtením 2x a přičtením 3: 2x=12, takže x=6.',2),
  ('linearni-rovnice-dan-v1-q11','linearni-rovnice-dan-v1',11,'{"instruction":"Kterou operací odstraníš člen −5 na levé straně?","math":"3x-5=10","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Přičteš 5 jen vlevo"},{"id":"b","label":"Přičteš 5 k oběma stranám"},{"id":"c","label":"Odečteš 5 od obou stran"},{"id":"d","label":"Vydělíš obě strany 5"}]','b','Správně přičteme 5 na obou stranách, pak 3x=15.',2),
  ('linearni-rovnice-dan-v1-q12','linearni-rovnice-dan-v1',12,'{"instruction":"V čem spočívá zkouška?","math":"2x+3=11,\\quad x=4","category":"02 / Ekvivalentní úpravy","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Dosadit 4 jen vlevo"},{"id":"b","label":"Dosadit 4 jen vpravo"},{"id":"c","label":"Dosadit x=4 do původních obou stran"},{"id":"d","label":"Ověřit jen mezikrok"}]','c','Levá strana 2·4+3=11, pravá 11; původní rovnice platí.',1),
  ('linearni-rovnice-dan-v1-q13','linearni-rovnice-dan-v1',13,'{"instruction":"Roznásob a vyřeš.","math":"3(x-2)=2x+1","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 1"},{"id":"b","label":"x = 3"},{"id":"c","label":"x = 7"},{"id":"d","label":"x = −7"}]','c','3x−6=2x+1, tedy x=7.',2),
  ('linearni-rovnice-dan-v1-q14','linearni-rovnice-dan-v1',14,'{"instruction":"Uprav dvě dvojice členů s x.","math":"2(3x-1)-4x=10","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 6"},{"id":"b","label":"x = 4"},{"id":"c","label":"x = −6"},{"id":"d","label":"x = 3"}]','a','6x−2−4x=10, tedy 2x=12 a x=6.',2),
  ('linearni-rovnice-dan-v1-q15','linearni-rovnice-dan-v1',15,'{"instruction":"Zaměř se na mínus před závorkou.","math":"-(x-5)+2x=9","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = −4"},{"id":"b","label":"x = 4"},{"id":"c","label":"x = 14"},{"id":"d","label":"x = 9"}]','b','−x+5+2x=9, tedy x+5=9 a x=4.',2),
  ('linearni-rovnice-dan-v1-q16','linearni-rovnice-dan-v1',16,'{"instruction":"Vyřeš složitější rovnici se závorkou.","math":"5-2(x+3)=-3","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 1"},{"id":"b","label":"x = −1"},{"id":"c","label":"x = 4"},{"id":"d","label":"x = 7"}]','a','5−2x−6=−3, tedy −1−2x=−3, odtud x=1.',2),
  ('linearni-rovnice-dan-v1-q17','linearni-rovnice-dan-v1',17,'{"instruction":"Kolik řešení má rovnice po roznásobení?","math":"4(x-1)=2(2x+3)","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Jedno: x=1"},{"id":"b","label":"Jedno: x=−1"},{"id":"c","label":"Žádné"},{"id":"d","label":"Nekonečně mnoho"}]','c','4x−4=4x+6 vede na nepravdivý výrok −4=6.',2),
  ('linearni-rovnice-dan-v1-q18','linearni-rovnice-dan-v1',18,'{"instruction":"Rozpoznej identitu.","math":"3(2x+1)=6x+3","category":"03 / Závorky a znaménka","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Žádné řešení"},{"id":"b","label":"Všechna reálná x"},{"id":"c","label":"Pouze x=1"},{"id":"d","label":"Pouze x=0"}]','b','Obě strany jsou 6x+3 pro všechna reálná x.',2),
  ('linearni-rovnice-dan-v1-q19','linearni-rovnice-dan-v1',19,'{"instruction":"Vyřeš rovnici.","math":"\\frac{x}{2}+3=8","category":"04 / Rovnice se zlomky","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 5"},{"id":"b","label":"x = 10"},{"id":"c","label":"x = 16"},{"id":"d","label":"x = −10"}]','b','x/2=5, násobením dvěma: x=10.',2),
  ('linearni-rovnice-dan-v1-q20','linearni-rovnice-dan-v1',20,'{"instruction":"Sečti výrazy s neznámou.","math":"\\frac{x}{3}+\\frac{x}{6}=3","category":"04 / Rovnice se zlomky","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 3"},{"id":"b","label":"x = 6"},{"id":"c","label":"x = 9"},{"id":"d","label":"x = 18"}]','b','2x/6+x/6=3x/6=x/2, tedy x=6.',2),
  ('linearni-rovnice-dan-v1-q21','linearni-rovnice-dan-v1',21,'{"instruction":"Nezapomeň vynásobit i konstantu.","math":"\\frac{x-2}{4}=3","category":"04 / Rovnice se zlomky","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 10"},{"id":"b","label":"x = 1"},{"id":"c","label":"x = 14"},{"id":"d","label":"x = 12"}]','c','x−2=12, tedy x=14.',2),
  ('linearni-rovnice-dan-v1-q22','linearni-rovnice-dan-v1',22,'{"instruction":"Vynásob obě strany třemi.","math":"\\frac{2x+1}{3}=5","category":"04 / Rovnice se zlomky","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 7"},{"id":"b","label":"x = 8"},{"id":"c","label":"x = 6"},{"id":"d","label":"x = 15"}]','a','2x+1=15, takže 2x=14 a x=7.',2),
  ('linearni-rovnice-dan-v1-q23','linearni-rovnice-dan-v1',23,'{"instruction":"Použij nejmenší společný násobek 3 a 2.","math":"\\frac{x-1}{3}+\\frac{x+2}{2}=4","category":"04 / Rovnice se zlomky","hint":"Po vynásobení celé rovnice šesti se zbavíš obou jmenovatelů."}','[{"id":"a","label":"x = 2"},{"id":"b","label":"x = 3"},{"id":"c","label":"x = 4"},{"id":"d","label":"x = 5"}]','c','Násobení šesti: 2(x−1)+3(x+2)=24; 5x+4=24; x=4.',3),
  ('linearni-rovnice-dan-v1-q24','linearni-rovnice-dan-v1',24,'{"instruction":"Urči x bez desetinných čísel.","math":"\\frac{x}{2}-\\frac{x}{3}=2","category":"04 / Rovnice se zlomky","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 6"},{"id":"b","label":"x = 12"},{"id":"c","label":"x = 3"},{"id":"d","label":"x = −12"}]','b','(3x−2x)/6=2, tedy x/6=2 a x=12.',2),
  ('linearni-rovnice-dan-v1-q25','linearni-rovnice-dan-v1',25,'{"instruction":"Urči počet řešení.","math":"3x+2=3x+5","category":"05 / Počet řešení a graf","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Jedno"},{"id":"b","label":"Žádné"},{"id":"c","label":"Dvě"},{"id":"d","label":"Nekonečně mnoho"}]','b','Odečtením 3x by muselo platit 2=5, což je spor.',2),
  ('linearni-rovnice-dan-v1-q26','linearni-rovnice-dan-v1',26,'{"instruction":"Urči množinu řešení.","math":"2(x+4)=2x+8","category":"05 / Počet řešení a graf","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Žádná"},{"id":"b","label":"Pouze x=4"},{"id":"c","label":"Všechna reálná x"},{"id":"d","label":"Pouze x=0"}]','c','Rovnost 2x+8=2x+8 platí pro každé reálné x.',2),
  ('linearni-rovnice-dan-v1-q27','linearni-rovnice-dan-v1',27,'{"instruction":"Co platí o rovnici?","math":"0\\cdot x=-7","category":"05 / Počet řešení a graf","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x=0"},{"id":"b","label":"x=−7"},{"id":"c","label":"Všechna reálná x"},{"id":"d","label":"Nemá řešení"}]','d','Po levé straně stále zůstává 0, tedy 0=−7 není možné.',2),
  ('linearni-rovnice-dan-v1-q28','linearni-rovnice-dan-v1',28,'{"instruction":"Uvažuj rovnici s parametrem.","math":"ax+5=5,\\quad a=0","category":"05 / Počet řešení a graf","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Právě jedno řešení"},{"id":"b","label":"Právě dvě řešení"},{"id":"c","label":"Nekonečně mnoho řešení"},{"id":"d","label":"Žádné řešení"}]','c','Při a=0 vychází identita 5=5 bez ohledu na x.',2),
  ('linearni-rovnice-dan-v1-q29','linearni-rovnice-dan-v1',29,'{"instruction":"Pro jaké b má rovnice nekonečně mnoho řešení?","math":"3x+b=3x+2","category":"05 / Počet řešení a graf","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"b = 0"},{"id":"b","label":"b = 2"},{"id":"c","label":"b = 3"},{"id":"d","label":"Pro žádné b"}]','b','Odečtením 3x dostaneme b=2. Pak jsou obě strany totožné.',2),
  ('linearni-rovnice-dan-v1-q30','linearni-rovnice-dan-v1',30,'{"instruction":"Urči x-ovou souřadnici průsečíku dvou přímek.","math":"y_1=2x+1,\\qquad y_2=-x+7","category":"05 / Počet řešení a graf","hint":"V průsečíku platí y1=y2."}','[{"id":"a","label":"x = 1"},{"id":"b","label":"x = 2"},{"id":"c","label":"x = 3"},{"id":"d","label":"Nemají průsečík"}]','b','Polož 2x+1=−x+7: 3x=6, tedy x=2.',3),
  ('linearni-rovnice-dan-v1-q31','linearni-rovnice-dan-v1',31,'{"instruction":"Tři stejné sešity a poštovné 20 Kč stojí 110 Kč. Kolik stojí jeden sešit?","math":"3x+20=110","category":"06 / Aplikace a diagnostika","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"20 Kč"},{"id":"b","label":"30 Kč"},{"id":"c","label":"40 Kč"},{"id":"d","label":"90 Kč"}]','b','3x=90 a x=30 Kč. Ověření 3·30+20=110.',3),
  ('linearni-rovnice-dan-v1-q32','linearni-rovnice-dan-v1',32,'{"instruction":"Dvojnásobek čísla zmenšený o 5 je 19. Urči číslo.","math":"2x-5=19","category":"06 / Aplikace a diagnostika","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"7"},{"id":"b","label":"12"},{"id":"c","label":"14"},{"id":"d","label":"24"}]','b','2x=24, proto x=12.',2),
  ('linearni-rovnice-dan-v1-q33','linearni-rovnice-dan-v1',33,'{"instruction":"Dva dospělí lístky stojí každý x Kč a dětský je o 30 Kč levnější. Celkem zaplatíš 330 Kč. Kolik stojí dospělý lístek?","math":"2x+(x-30)=330","category":"06 / Aplikace a diagnostika","hint":"Sečti ceny všech tří vstupenek."}','[{"id":"a","label":"100 Kč"},{"id":"b","label":"110 Kč"},{"id":"c","label":"120 Kč"},{"id":"d","label":"150 Kč"}]','c','3x−30=330, tedy 3x=360 a x=120 Kč.',3),
  ('linearni-rovnice-dan-v1-q34','linearni-rovnice-dan-v1',34,'{"instruction":"Je hodnota x=−2 řešením rovnice?","math":"2x+3=-1","category":"06 / Aplikace a diagnostika","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"Ano"},{"id":"b","label":"Ne, vychází 1"},{"id":"c","label":"Ne, vychází −7"},{"id":"d","label":"Nelze určit"}]','a','Po dosazení 2·(−2)+3=−1, tedy ano.',1),
  ('linearni-rovnice-dan-v1-q35','linearni-rovnice-dan-v1',35,'{"instruction":"Rovnice vyjadřuje čtyřnásobek čísla zvýšeného o 3 roven 28. Urči x.","math":"4(x+3)=28","category":"06 / Aplikace a diagnostika","hint":"Proveď stejnou ekvivalentní úpravu na obou stranách a výsledek ověř dosazením."}','[{"id":"a","label":"x = 4"},{"id":"b","label":"x = 7"},{"id":"c","label":"x = 10"},{"id":"d","label":"x = −4"}]','a','x+3=7, takže x=4. Závorka je součástí násobeného výrazu.',2),
  ('linearni-rovnice-dan-v1-q36','linearni-rovnice-dan-v1',36,'{"instruction":"Pro jaké p nemá rovnice řešení?","math":"(p-2)x=6","category":"06 / Aplikace a diagnostika","hint":"Zkoumej případ, kdy je koeficient u x nulový."}','[{"id":"a","label":"p = 0"},{"id":"b","label":"p = 1"},{"id":"c","label":"p = 2"},{"id":"d","label":"p = 3"}]','c','Při p=2 vznikne 0·x=6, což je spor. Pro jiné p existuje x=6/(p−2).',3);
